mapper.select:
SELECT r.id, r.room_number, r.rent, a.id apt_id, a.name apt_name, a.address_detail apt_address_detail,
       a.city_id apt_city_id, a.district_id apt_district_id, a.province_id apt_province_id,
       a.city_name apt_city_name, a.province_name apt_province_name, a.district_name apt_district_name
FROM room_info r JOIN apartment_info a ON a.id=r.apartment_id
WHERE r.is_deleted=0 AND a.is_deleted=0 AND r.is_release=1 AND a.is_release=1
AND a.id=#{apartmentId}
AND a.province_id=#{query.provinceId}
AND a.city_id=#{query.cityId}
AND a.district_id=#{query.districtId}
AND r.rent >= #{query.minRent}
AND r.rent <= #{query.maxRent}

    AND EXISTS (SELECT 1 FROM room_payment_type p WHERE p.room_id=r.id
                AND p.payment_type_id=#{query.paymentTypeId} AND p.is_deleted=0)

ORDER BY

    r.rent DESC,
    r.rent ASC,

r.id
